original.observe.js:
async (spec) => {
  const one = (selector) => document.querySelector(selector);
  const all = (selector) => Array.from(document.querySelectorAll(selector));
  const remote = '[data-testid="branch-section-remote"]';
  const branch = (name) => all(`${remote} [data-testid="branch-row"] [title]`)
    .filter((node) => node.title === name && node.textContent.trim() === name);
  const commit = (summary, oid) => all('[data-testid="commit-row-summary"]')
    .filter((node) => {
      const sha = node.closest('[data-testid="commit-row"]')
        ?.querySelector('[data-column="sha"]')?.textContent.trim();
      return node.textContent.trim() === summary && sha?.length >= 7 && oid.startsWith(sha);
    });
  const rows = (kind) => all(`[data-testid="staging-${kind}-section"] [data-testid="staging-file"]`);
  const fileRowCorrect = () => {
    const [row, ...others] = rows('unstaged');
    return Boolean(row && !others.length && !rows('staged').length &&
      row.querySelector(':scope > span > span:first-child')?.textContent.trim() === 'M' &&
      Array.from(row.querySelectorAll('span')).some((node) =>
        !node.children.length && node.textContent.trim() === spec.path));
  };
  if (!one('[data-testid="staging-unstaged-section"]') || rows('unstaged').length ||
      rows('staged').length || commit(spec.baseSummary, spec.baseOid).length !== 1 ||
      branch('main').length !== 1 || branch(spec.branch).length ||
      (spec.incomingOid && commit(spec.incomingSummary, spec.incomingOid).length)) {
    throw new Error('unexpected starting staging, branch or graph contents');
  }

  const tauri = window.__TAURI_INTERNALS__;
  const now = () => performance.now();
  const state = {
    rowMs: null, branchMs: null, graphMs: null, refReadyMs: null, fetchStartMs: null,
    fetchCompleteMs: null, fetchReport: null, fetchError: null, events: [],
  };
  await tauri.invoke('plugin:event|listen', {
    event: 'repo-changed', target: {kind: 'Any'},
    handler: tauri.transformCallback(({payload}) => {
      if (payload.repo === spec.repo && state.events.length < 40) {
        state.events.push({atMs: now(), ...payload});
      }
    }),
  });

  let sawRow;
  const row = new Promise((resolve) => { sawRow = resolve; });
  let sawRef;
  const ref = spec.incomingOid
    ? new Promise((resolve) => { sawRef = resolve; }) : Promise.resolve();
  const observer = new MutationObserver(() => {
    const tick = now();
    if (state.rowMs === null && fileRowCorrect()) {
      state.rowMs = tick;
      sawRow(tick);
    }
    if (spec.incomingOid) {
      const hasBranch = branch(spec.branch).length === 1;
      const hasCommit = commit(spec.incomingSummary, spec.incomingOid).length === 1;
      if (state.branchMs === null && hasBranch) state.branchMs = tick;
      if (state.graphMs === null && hasCommit) state.graphMs = tick;
      if (state.refReadyMs === null && hasBranch && hasCommit) {
        state.refReadyMs = tick;
        sawRef();
      }
    }
  });
  observer.observe(document.body, {subtree: true, childList: true, characterData: true});
  let fetch = Promise.resolve();
  const read = () => ({...state, fileRowCorrect: fileRowCorrect(),
    incomingBranchCount: branch(spec.branch).length,
    incomingGraphCount: spec.incomingOid ? commit(spec.incomingSummary, spec.incomingOid).length : 0});
  window.trunk440 = {
    read,
    start(command) {
      if (state.fetchStartMs !== null) throw new Error('fetch already started');
      state.fetchStartMs = now();
      const args = command === 'git_fetch_background'
        ? {path: spec.repo, intervalMs: 0} : {path: spec.repo};
      fetch = tauri.invoke(command, args).then(
        (report) => { state.fetchCompleteMs = now(); state.fetchReport = report; },
        (error) => { state.fetchCompleteMs = now(); state.fetchError = String(error); },
      );
      return state.fetchStartMs;
    },
    row: () => row,
    async result(expectedBackgroundOutcome) {
      await fetch;
      if (!state.fetchError && (!expectedBackgroundOutcome ||
        state.fetchReport?.remotes?.[0]?.outcome === expectedBackgroundOutcome)) {
        await Promise.all([row, ref]);
      }
      observer.disconnect();
      return read();
    },
  };
  return read();
}
